#!/system/bin/sh
# SPEC 04 rows (drivers612/SPEC/04-camera-video-gpu-security.md): camera HAL static metadata per id, camera sysfs, video
# codec nodes, GPU (kgsl sysfs, GL/Vulkan identity, fault counters), TEE (TA files, listeners, HALs), keystore/encryption
# state, DRM/HDCP nodes, device-integrity tells that depend on the kernel, platform features (cgroup v2, incfs, fuse, tracing,
# batterystats inputs, virtualization), root stack. READ-ONLY and SILENT: no camera is opened, nothing is captured, played,
# encoded or written; one scratch directory under the sweep's own directory. No identifier is printed: unique values
# (module ids, sensor ids, serials, digests) appear as length + 12-hex hash only.
# NEVER read here (they drive hardware when read): /sys/class/camera/ois/* (selftest, calibration, hall reads),
# /sys/class/camera/af/*, /sys/class/camera/ssm/*, /sys/class/camera/flash/*, *_hwparam (clears the error counters),
# rear_camfw_load, isp_core, anything under /sys/class/lcd/panel.
. "${0%/*}/../dev-lib.sh"
T="${0%/*}/../spec04.$$"; mkdir -p "$T" 2>/dev/null || T=/data/local/tmp/.st-spec04.$$; mkdir -p "$T"; trap 'rm -rf "$T"' EXIT
up=$(cut -d. -f1 /proc/uptime)
one() { tr '\n' ' ' | tr -s ' ' | sed -e 's/^ //' -e 's/ $//'; }
lsn() { ls "$1" 2>/dev/null | grep -vE '^(power|subsystem|uevent|device)$' | tr '\n' ' '; }

# =========================================================================== camera
# dumpsys into a FILE (dev-lib.sh D explains why a pipe kills the provider), then parse the file
timeout 40 dumpsys media.camera > "$T/cam.txt" 2>&1
pd0=$(dmesg 2>/dev/null | grep -cE "camera-provider[^ ]*' \(pid [0-9]+\) (received|exited)")
if [ "$(grep -c . "$T/cam.txt")" -lt 20 ]; then C camera.hal_ids FAIL kernel+ROM "no camera dump" "dumpsys media.camera gave $(grep -c . "$T/cam.txt") lines at uptime $up s (the provider registers late: sweep at >= 120 s)"
else
	ids=$(grep -oE '^== Camera HAL device device@[0-9.]+/[a-z]+/[0-9]+ .*static information' "$T/cam.txt" | grep -oE '/[0-9]+ ' | tr -d '/ ' | sort -un | one)
	[ -n "$ids" ] && C camera.hal_ids PASS kernel+ROM "set: $(for i in $ids; do printf 'id%s ' "$i"; done)" "HAL devices incl. the ones hidden from apps; $(grep -m1 -oE 'static info: [0-9]+ devices' "$T/cam.txt")" || C camera.hal_ids FAIL kernel+ROM "no HAL device section" "$(head -3 "$T/cam.txt" | one)"
	C camera.public_ids "$(grep -qE 'Device [0-9]+ maps to' "$T/cam.txt" && echo PASS || echo FAIL)" kernel+ROM "$(grep -E '^ *Number of (normal )?camera devices|^ *Device [0-9]+ maps to' "$T/cam.txt" | tr -s ' ' | tr '\n' ';')"
	kv() { sed -n "/ $2 (/,/): [a-z0-9]*\[/{/^ *\[/p;}" "$1" | tr -d '[]' | one; }      # the value lines after one metadata key
	hl=; cp=; fp=; hs=; ms=; sh=; st=
	for i in $ids; do
		sed -n "/^== Camera HAL device device@[0-9.]*\/[a-z]*\/$i (.*static information/,/dumpState: ==/p" "$T/cam.txt" | grep -v '^== Camera HAL device' > "$T/c.$i"
		sh="$sh id$i=$(sha256sum < "$T/c.$i" | cut -c1-12)/$(grep -c . "$T/c.$i")"
		hl="$hl id$i=$(kv "$T/c.$i" android.info.supportedHardwareLevel | tr -d ' ')"
		cp="$cp id$i=$(kv "$T/c.$i" android.request.availableCapabilities | tr ' ' ',')"
		fp="$fp id$i=$(kv "$T/c.$i" android.control.aeAvailableTargetFpsRanges | tr ' ' ',')"
		h=$(kv "$T/c.$i" android.control.availableHighSpeedVideoConfigurations | tr ' ' ','); hx=$(kv "$T/c.$i" samsung.android.scaler.availableHighSpeedVideoConfigurations | tr ' ' ',')
		hs="$hs id$i=${h:--}/${hx:--}"
		# stream table: rows are [format width height OUTPUT|INPUT]; keep the row count and the largest size per format+direction
		sc=$(sed -n "/ android.scaler.availableStreamConfigurations (/,/): [a-z0-9]*\[/{/^ *\[/p;}" "$T/c.$i" | tr -d '[]' | tr -s ' ' | sed 's/^ //')
		so=; for f in $(printf '%s\n' "$sc" | cut -d' ' -f1,4 | sort -u | tr ' ' '/'); do fm=${f%/*}; dr=${f#*/}
			rows=$(printf '%s\n' "$sc" | grep -E "^$fm [0-9]+ [0-9]+ $dr"); mx=0; mw=; for r in $(printf '%s\n' "$rows" | cut -d' ' -f2,3 | tr ' ' 'x'); do w=${r%x*}; hh=${r#*x}; a=$((w*hh)); [ "$a" -gt "$mx" ] && { mx=$a; mw=$r; }; done
			so="$so,f$fm/$dr:$(printf '%s\n' "$rows" | grep -c .):$mw"; done
		st="$st id$i=${so#,}"
		ms="$ms id$i=facing:$(grep -m1 -oE 'Facing: [A-Za-z]+' "$T/c.$i" | cut -d' ' -f2),flash:$(grep -m1 -oE 'Has a flash unit: [a-z]+' "$T/c.$i" | cut -d' ' -f5),orient:$(grep -m1 -oE 'Orientation: [0-9]+' "$T/c.$i" | cut -d' ' -f2),pix:$(kv "$T/c.$i" android.sensor.info.pixelArraySize | tr ' ' 'x'),ois:$(kv "$T/c.$i" android.lens.info.availableOpticalStabilization | tr ' ' '+'),vstab:$(kv "$T/c.$i" android.control.availableVideoStabilizationModes | tr ' ' '+'),phys:$(kv "$T/c.$i" android.logicalMultiCamera.physicalIds | tr -c 'A-Za-z0-9\n' '+'),torch:$(kv "$T/c.$i" android.flash.info.strengthMaximumLevel),jpegmax:$(kv "$T/c.$i" android.jpeg.maxSize),keys:$(grep -m1 -oE 'metadata array: [0-9]+' "$T/c.$i" | cut -d' ' -f3)"
	done
	[ -n "$ids" ] && {
		C camera.hal_static_hash PASS kernel+ROM "set:$sh" "sha256/lines of each id's whole static block (every metadata key incl. vendor keys, conflicts, resource cost): a different hash = the HAL saw different hardware, calibration or driver limits; then read the rows below"
		C camera.hal_level PASS kernel+ROM "set:$hl" "supportedHardwareLevel per id (3 = LEVEL_3)"
		C camera.hal_caps PASS kernel+ROM "set:$cp" "availableCapabilities per id"
		C camera.hal_fps PASS kernel+ROM "set:$fp" "aeAvailableTargetFpsRanges per id (pairs)"
		C camera.hal_highspeed PASS kernel+ROM "set:$hs" "high-speed video configurations per id: android key / samsung key (w,h,fps_min,fps_max,batch)"
		C camera.hal_streams PASS kernel+ROM "set:$st" "per id: f<format>/<direction>:<rows>:<largest size> (33 JPEG, 34 PRIVATE, 35 YUV, 32 RAW16, 37 RAW10, 36 RAW_PRIVATE)"
		C camera.hal_misc PASS kernel+ROM "set:$ms" "facing, flash unit, orientation, pixel array, OIS modes, video stabilisation modes, physical ids, torch levels, max JPEG bytes, key count"
	}
	ev=$(sed -n '/Camera service events log/,/^== Camera /p' "$T/cam.txt" | grep -cE 'REMOVE device|has died')
	pd1=$(dmesg 2>/dev/null | grep -cE "camera-provider[^ ]*' \(pid [0-9]+\) (received|exited)")
	C camera.provider_deaths "$([ "${pd1:-0}" = 0 ] && [ "${ev:-0}" = 0 ] && echo PASS || echo FAIL)" kernel+ROM "init log: ${pd1:-0} provider exits, service log: ${ev:-0} removals" "before this script: ${pd0:-0}; a count that grows during the sweep = a check killed the provider (dumpsys piped into head)"
fi
# every /sys/class/camera directory: attribute NAMES only (rear/front are rows of 30-hw.sh)
for d in /sys/class/camera/*; do [ -d "$d" ] || continue; n=${d##*/}; case "$n" in rear|front) continue;; esac; setl "camera.sysfs.$n" kernel 0 "$(lsn $d)"; done
# identity values that are plain show() functions (firmware strings, part names, version checks); unique ids hashed
cv=; for a in rear/rear_camfw_full rear/rear2_camfw_full rear/rear3_camfw_full rear/rear4_camfw_full front/front_camfw_full rear/rear_caminfo rear/rear2_caminfo rear/rear3_caminfo rear/rear4_caminfo front/front_caminfo \
	rear/rear_checkfw_user rear/rear_checkfw_factory rear/rear2_checkfw_user rear/rear3_checkfw_user rear/rear4_checkfw_user front/front_checkfw_user front/front_checkfw_factory rear/supported_cameraIds rear/rear_calcheck; do
	[ -r /sys/class/camera/$a ] && cv="$cv ${a#*/}=[$(rd /sys/class/camera/$a | tr ' ' '_')]"; done
C camera.sysfs_identity "$([ -n "$cv" ] && echo PASS || echo FAIL)" kernel "set:$cv" "firmware/calibration header versions, ISP/sensor info, version checks, supported ids"
cu=; for a in rear/rear_moduleid rear/rear2_moduleid rear/rear3_moduleid rear/rear4_moduleid front/front_moduleid rear/rear_sensorid_exif rear/rear2_sensorid_exif rear/rear3_sensorid_exif rear/rear4_sensorid_exif front/front_sensorid_exif \
	rear/rear_mtf_exif rear/rear_afcal rear/rear_paf_cal_check rear/rear2_dualcal_size rear/rear3_dualcal_size rear/rear4_dualcal_size rear/rear2_tilt rear/rear3_tilt rear/rear4_tilt front/front_afcal front/front_mtf_exif; do
	[ -r /sys/class/camera/$a ] && { v=$(head -c 4096 /sys/class/camera/$a 2>/dev/null | od -An -tx1 | tr -d ' \n'); cu="$cu ${a#*/}=$((${#v}/2))b:$(h12 "$v")"; }; done
C camera.sysfs_calibration "$([ -n "$cu" ] && echo PASS || echo FAIL)" kernel "set:$cu" "EEPROM/OTP-derived values (module id, sensor id, MTF, AF/PAF calibration, dual-cal size, tilt) as byte count + hash: equal on both kernels = the same calibration reaches the HAL"
setl camera.v4l_names kernel 4 "$(for n in /sys/class/video4linux/*/name; do [ -r "$n" ] && printf '%s:%s\n' "$(basename "${n%/name}" | tr -d '0-9')" "$(rd "$n" | tr ' ' '_')"; done | sort | uniq -c | sed -E 's/^ *([0-9]+) (.*)/\2x\1/' | tr '\n' ' ')"
nodes camera.dev_extra kernel /dev/video0 /dev/video1 /dev/media0 /dev/media1
C camera.sync_nodes PASS kernel "synx_device=$([ -e /dev/synx_device ] && echo y || echo n) cvp=$(ls /dev 2>/dev/null | grep -ciE '^(cvp|video-cvp|msm_cvp)') npu=$([ -e /dev/msm_npu ] && echo y || echo n)" "cvp nodes: $(ls /dev 2>/dev/null | grep -iE 'cvp' | one); labels: $(lz /dev/synx_device) $(lz /dev/video0)"
setl camera.fw_files kernel+ROM 2 "$(for f in CAMERA_ICP.elf CAMERA_ICP_170.elf evass.mdt evass-lt.mdt ois_mcu_stm32g_fw.bin; do for d in /vendor/firmware /vendor/firmware_mnt/image; do [ -e $d/$f ] && echo "$f"; done; done | sort -u | tr '\n' ' ')"
C camera.thermal_zones PASS kernel "set: $(for z in /sys/class/thermal/thermal_zone*/type; do rd $z; echo; done | grep -iE 'cam' | sort -u | one)" "cooling devices: $(for z in /sys/class/thermal/cooling_device*/type; do rd $z; echo; done | grep -iE 'cam|flash|led' | sort -u | one)"
C camera.kernel_errors "$([ "$(dmesg 2>/dev/null | grep -cE 'CAM_ERR')" -le 0 ] && echo PASS || echo FAIL)" kernel "$(dmesg 2>/dev/null | grep -cE 'CAM_ERR') CAM_ERR lines" "$(dmesg 2>/dev/null | grep -E 'CAM_ERR' | sed -E 's/^\[[ 0-9.]+\] *//; s/[0-9]+/N/g' | sort | uniq -c | sort -rn | head -4 | cut -c1-150 | tr '\n' ';')"

# =========================================================================== video codecs
setl codec.v4l_nodes kernel 1 "$(for n in /sys/class/video4linux/video3[0-9]/name /sys/class/video4linux/video[4-9][0-9]/name; do [ -r "$n" ] && echo "$(basename "${n%/name}")=$(rd "$n" | tr ' ' '_')"; done | tr '\n' ' ')"
setl codec.venus_fw kernel+ROM 0 "$(ls /vendor/firmware /vendor/firmware_mnt/image 2>/dev/null | grep -iE '^(vpu|venus)' | sed -E 's/\.(b[0-9]+|mdt|mbn)$//' | sort -u | tr '\n' ' ')"
setl codec.services kernel+ROM 1 "$(getprop | grep -oE '^\[init\.svc\.[^]]*(codec|omx|c2|media\.swcodec|mediacodec)[^]]*\]: \[[a-z]+' | sed -e 's/^\[init\.svc\.//' -e 's/\]: \[/=/' | tr '\n' ' ')"
setl codec.xml kernel+ROM 1 "$(for f in /vendor/etc/media_codecs*.xml /odm/etc/media_codecs*.xml /system/etc/media_codecs*.xml /apex/com.android.media.swcodec/etc/media_codecs*.xml; do [ -r "$f" ] && echo "${f##*/}:$(sha256sum < "$f" | cut -c1-8)"; done | sort -u | tr '\n' ' ')"
C codec.props PASS kernel+ROM "$(for p in ro.media.xml_variant.codecs ro.media.xml_variant.codecs_performance debug.stagefright.ccodec debug.stagefright.omx_default_rank vendor.media.target_variant vendor.media.target.version media.settings.xml vendor.vidc.debug.level ro.vendor.qti.va_aosp.support persist.vendor.media.hdr10plus.enable; do echo "$p=$(getprop $p)"; done | one)"
C codec.kernel_errors "$([ "$(dmesg 2>/dev/null | grep -cE 'msm_vidc.*(err|fail)|venus.*(fail|error|fatal)|vidc.*sys error')" = 0 ] && echo PASS || echo FAIL)" kernel "$(dmesg 2>/dev/null | grep -cE 'msm_vidc.*(err|fail)|venus.*(fail|error|fatal)|vidc.*sys error') vidc/venus error lines" "$(dmesg 2>/dev/null | grep -E 'msm_vidc.*(err|fail)|venus.*(fail|error|fatal)|vidc.*sys error' | sed -E 's/^\[[ 0-9.]+\] *//; s/[0-9a-f]{6,}/N/g' | sort | uniq -c | sort -rn | head -3 | cut -c1-150 | tr '\n' ';')"

# =========================================================================== GPU
G=/sys/class/kgsl/kgsl-3d0
setl gpu.kgsl_attrs kernel 10 "$(lsn $G)"
setl gpu.kgsl_dirs kernel 0 "$(for d in $G/*/; do [ -d "$d" ] || continue; n=$(basename "$d"); case "$n" in power|subsystem|device) continue;; esac; echo "$n:$(ls "$d" 2>/dev/null | grep -c .)"; done | tr '\n' ' ')"
gv=; for a in gpu_model max_gpuclk max_clock_mhz min_clock_mhz num_pwrlevels max_pwrlevel min_pwrlevel default_pwrlevel thermal_pwrlevel preemption preempt_level preempt_count skipsaverestore usesgmem hwcg lm bus_split ifpc acd bcl throttling \
	idle_timer wake_timeout pm_qos_active_latency force_clk_on force_bus_on force_rail_on force_no_nap ft_policy ft_pagefault_policy ft_long_ib_detect ft_hang_intr_status perfcounter l3_vote context_aware_dcvs_enabled; do
	[ -r $G/$a ] && gv="$gv $a=$(rd $G/$a | tr ' ' '_' | cut -c1-40)"; done
C gpu.kgsl_values "$([ -n "$gv" ] && echo PASS || echo FAIL)" kernel "set:$gv" "tunables as the kernel set them (power levels, preemption, IFPC/ACD/BCL, fault tolerance policy); idle_timer etc. may be rewritten by the perf HAL"
C gpu.freq_table "$([ -r $G/gpu_available_frequencies ] && echo PASS || echo FAIL)" kernel "$(rd $G/gpu_available_frequencies)" "devfreq governor $(rd $G/devfreq/governor) of [$(rd $G/devfreq/available_governors)]; min $(rd $G/devfreq/min_freq) max $(rd $G/devfreq/max_freq) now $(rd $G/gpuclk) Hz busy $(rd $G/gpu_busy_percentage)"
setl gpu.sysfs_kernel_gpu kernel 0 "$(lsn /sys/kernel/gpu)"
fc=$(rd $G/snapshot/faultcount)
C gpu.faults "$([ "${fc:-0}" = 0 ] && [ "$(dmesg 2>/dev/null | grep -cE 'kgsl.*(gpu fault|fault ctx|hang detected|GMU.*(fail|timeout)|snapshot created)|adreno.*fault')" = 0 ] && echo PASS || echo FAIL)" kernel "snapshot faultcount=${fc:-absent}" "kgsl fault lines in the kernel log: $(dmesg 2>/dev/null | grep -cE 'kgsl.*(gpu fault|fault ctx|hang detected|GMU.*(fail|timeout)|snapshot created)|adreno.*fault'); snapshot dir: $(lsn $G/snapshot); a fault count above 0 = the GPU hung and recovered since boot"
setl gpu.fw_files kernel+ROM 2 "$(ls /vendor/firmware /vendor/firmware_mnt/image 2>/dev/null | grep -E '^a6[0-9]{2}_(sqe|gmu|zap)|^a6[0-9]{2}.*zap' | sed -E 's/\.(b[0-9]+|mdt|mbn|elf|fw|bin)$//' | sort -u | tr '\n' ' ')"
timeout 25 dumpsys SurfaceFlinger > "$T/sf.txt" 2>/dev/null
gl=$(grep -m1 -E '^ *GLES: ' "$T/sf.txt" | sed 's/^ *GLES: //')
C gpu.gles "$([ -n "$gl" ] && echo PASS || echo FAIL)" kernel+ROM "${gl:-no GLES line}" "renderengine: $(grep -m1 -oE 'RenderEngine[^,]*(Skia|GL|Vk|Vulkan)[A-Za-z]*' "$T/sf.txt" | head -1) backend prop $(getprop debug.renderengine.backend) hwui $(getprop debug.hwui.renderer)/$(getprop ro.hwui.use_vulkan)"
setl gpu.gl_extensions_protected kernel+ROM 0 "$(grep -oE 'EGL_EXT_protected_content|GL_EXT_protected_textures|EGL_KHR_gl_colorspace|EGL_EXT_gl_colorspace_bt2020_pq|EGL_EXT_gl_colorspace_display_p3|EGL_ANDROID_get_frame_timestamps|EGL_IMG_context_priority|GL_EXT_YUV_target|GL_OES_EGL_image_external_essl3|EGL_KHR_no_config_context|EGL_EXT_pixel_format_float|GL_EXT_texture_filter_anisotropic|GL_KHR_texture_compression_astc_ldr|GL_ANDROID_extension_pack_es31a' "$T/sf.txt" | sort -u | tr '\n' ' ')"
timeout 25 cmd gpu vkjson > "$T/vk.json" 2>/dev/null
api=$(grep -m1 -oE '"apiVersion" *: *[0-9]+' "$T/vk.json" | grep -oE '[0-9]+$'); drv=$(grep -m1 -oE '"driverVersion" *: *[0-9]+' "$T/vk.json" | grep -oE '[0-9]+$'); dn=$(grep -m1 -oE '"deviceName" *: *"[^"]*"' "$T/vk.json" | cut -d'"' -f4)
grep -oE '"extensionName" *: *"[^"]+"' "$T/vk.json" | cut -d'"' -f4 | sort -u > "$T/vkext.txt"; ne=$(grep -c . "$T/vkext.txt")
if [ -n "$api" ]; then C gpu.vulkan PASS kernel+ROM "api=$((api>>22)).$(((api>>12)&1023)).$((api&4095)) device=$(printf '%s' "$dn" | tr ' ' '_') driverVersion=$drv extensions=$ne/$(sha256sum < "$T/vkext.txt" | cut -c1-12)" "from cmd gpu vkjson (no Vulkan instance of ours)"
	h=$(( (ne + 1) / 2 )); setl gpu.vulkan_ext.1 kernel+ROM 0 "$(head -n "$h" "$T/vkext.txt" | tr '\n' ' ')"; setl gpu.vulkan_ext.2 kernel+ROM 0 "$(tail -n +"$((h+1))" "$T/vkext.txt" | tr '\n' ' ')"
else C gpu.vulkan FAIL kernel+ROM "no vkjson" "cmd gpu vkjson gave $(wc -c < "$T/vk.json") bytes"; fi
setl gpu.features kernel+ROM 1 "$(pm list features 2>/dev/null | grep -E 'vulkan|opengles|gamepad$' | sed 's/^feature://' | tr '\n' ' ')$(dumpsys package 2>/dev/null > /dev/null; echo "reqGlEsVersion=$(getprop ro.opengles.version)")"
C gpu.props PASS kernel+ROM "$(for p in ro.hardware.egl ro.hardware.vulkan ro.board.platform ro.gfx.driver.0 ro.gfx.driver.1 ro.gfx.angle.supported persist.graphics.egl ro.egl.blobcache.multifile graphics.gpu.profiler.support; do echo "$p=$(getprop $p)"; done | one)"
C gpu.mem_accounting "$([ -d /sys/kernel/tracing/events/gpu_mem ] || [ -d /sys/kernel/debug/tracing/events/gpu_mem ] && echo PASS || echo FAIL)" kernel "gpu_mem tracepoint=$([ -d /sys/kernel/tracing/events/gpu_mem ] && echo y || echo n) bpf map=$(ls /sys/fs/bpf 2>/dev/null | grep -c gpuMem) gpu_work=$(ls /sys/kernel/tracing/events/power 2>/dev/null | grep -c gpu_work_period) kgsl/proc=$([ -d /sys/class/kgsl/kgsl/proc ] && echo y || echo n)" "dumpsys gpu: $(timeout 10 dumpsys gpu --gpumem 2>/dev/null > "$T/gm.txt"; grep -m1 -iE 'total' "$T/gm.txt" | cut -c1-80)"
C gpu.thermal PASS kernel "set: $(for z in /sys/class/thermal/cooling_device*/type; do rd $z; echo; done | grep -iE 'gpu|kgsl' | sort -u | one)" "zones: $(for z in /sys/class/thermal/thermal_zone*/type; do rd $z; echo; done | grep -iE 'gpu' | sort -u | one)"

# =========================================================================== TEE / keystore / DRM
I=/vendor/firmware_mnt/image
setl tee.ta_files kernel+ROM 5 "$(ls $I 2>/dev/null | grep -E '\.mdt$' | sed 's/\.mdt$//' | sort -u | tr '\n' ' ')"
setl tee.ta_files_vendor kernel+ROM 0 "$(for d in /vendor/firmware /vendor/tee /vendor/app/mcRegistry /odm/firmware /system/etc/firmware; do ls $d 2>/dev/null | grep -E '\.mdt$|\.tlbin$|\.tabin$|^[0-9a-f]{32}' | sed -E 's/\.(mdt|tlbin|tabin)$//' ; done | sort -u | tr '\n' ' ')"
C tee.firmware_mnt "$(grep -q " /vendor/firmware_mnt " /proc/mounts && echo PASS || echo FAIL)" kernel+ROM "$(grep ' /vendor/firmware_mnt ' /proc/mounts | cut -d' ' -f3,4 | cut -c1-60)" "$(ls $I 2>/dev/null | grep -c .) files"
logcat -d -b main,system 2>/dev/null > "$T/lc.txt"
ls1=$(grep -oE 'QSEECOMD: : [A-Za-z ]+: Started \(Listener ID = [0-9]+\)' "$T/lc.txt" | sed -E 's/QSEECOMD: : //; s/: Started \(Listener ID = /=/; s/\)//; s/ /_/g' | sort -u | one)
C tee.listeners "$([ -n "$ls1" ] && echo PASS || echo SKIP)" kernel+ROM "${ls1:+set: $ls1}${ls1:-no qseecomd listener line left in logcat}" "total announced: $(grep -m1 -oE 'Total listener services to start = [0-9]+' "$T/lc.txt" | grep -oE '[0-9]+$'); dlopen failures: $(grep -oE 'QSEECOMD: : Init dlopen\([a-z0-9A-Z_.]+' "$T/lc.txt" | sort -u | grep -c .) libs tried, failed: $(grep -E 'QSEECOMD: : Init dlopen.*failed' "$T/lc.txt" | grep -oE 'dlopen\([A-Za-z0-9_.]+' | sort -u | cut -d'(' -f2 | one)"
C tee.shm_bridge PASS kernel "a52_no_shm_bridge=$(rd /sys/module/qcom_scm/parameters/a52_no_shm_bridge)$([ -e /sys/module/qcom_scm/parameters/a52_no_shm_bridge ] || echo 'n/a')" "5.4 never enables the TZ SHM bridge; on 6.12 it must be off (Y/1) or Samsung's PROCA/VaultKeeper TAs cannot map HLOS memory; qtee_shmbridge dir: $([ -d /sys/module/qtee_shmbridge ] && echo y || echo n)"
C tee.rpmb_path "$([ -n "$(ls /dev/bsg 2>/dev/null)" ] && echo PASS || echo FAIL)" kernel "set: $(ls /dev/bsg 2>/dev/null | one)" "RPMB listener goes through the UFS bsg/sg node; labels $(ls -Z /dev/bsg 2>/dev/null | sed -e 's/u:object_r://' -e 's/:s0//' | one | cut -c1-160)"
C tee.tzlog PASS kernel "tzdbg=$([ -d /sys/kernel/debug/tzdbg ] && echo debugfs || { [ -d /proc/tzdbg ] && echo proc || echo absent; })" "qsee_log readable: $([ -r /sys/kernel/debug/tzdbg/qsee_log ] || [ -r /proc/tzdbg/qsee_log ] && echo y || echo n)"
hal=$(lshal 2>/dev/null | grep -oE '(android\.hardware|vendor\.[a-z.]+)\.(keymaster|gatekeeper|weaver|drm|confirmationui|biometrics\.[a-z]+|secure_element|authsecret|oemlock|security\.[a-z.]+|qseecom|trustedui|tui_comm|sm|hdcp|wvkprov|proca|vaultkeeper|drk|skpm|engmode|hdm|fkeymaster|snap|sehradio)[A-Za-z.]*@[0-9.]+::I[A-Za-z]+/[A-Za-z0-9_.-]+' | sort -u | tr '\n' ' ')
setl tee.hidl_hals kernel+ROM 3 "$hal"
